<?php
if (!defined('ABSPATH')) exit;
add_shortcode('gim_app',function($atts){ $a=shortcode_atts(['page'=>''],$atts); ob_start(); gim_render_notice(); $page=$a['page']; if($page==='gim-login')gim_screen_login(); elseif($page==='gim-customer-dashboard')gim_screen_customer_dashboard(); elseif($page==='gim-provider-dashboard')gim_screen_provider_dashboard(); elseif($page==='gim-admin-dashboard')gim_screen_admin_dashboard(); elseif($page==='gim-book-service')gim_screen_book_service(); elseif($page==='gim-provider-directory')gim_screen_provider_directory(); elseif($page==='gim-provider-apply')gim_screen_provider_apply(); elseif($page==='gim-job')gim_screen_job(); elseif($page==='gim-payment-return')gim_screen_payment_return(); elseif($page==='gim-disputes')gim_screen_disputes(); else echo '<div class="gim-card">GOTITMATE</div>'; return ob_get_clean(); });
function gim_nonce_ok($action){ return isset($_POST['_wpnonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['_wpnonce'])),$action); }
function gim_screen_login(){
 if(is_user_logged_in()){echo '<main class="gim-shell"><div class="gim-card"><p>You are logged in.</p><a class="gim-btn" href="'.esc_url(gim_dashboard_url()).'">Open dashboard</a></div></main>';return;}
 if($_SERVER['REQUEST_METHOD']==='POST'&&gim_nonce_ok('gim_register')){ $r=gim_register_customer(sanitize_email($_POST['email']??''),(string)($_POST['password']??''),gim_post_text('name')); if(is_wp_error($r))echo '<div class="gim-alert gim-error">'.esc_html($r->get_error_message()).'</div>'; else echo '<div class="gim-alert">Account created. Check your email for the 6-digit verification code.</div>'; }
 if($_SERVER['REQUEST_METHOD']==='POST'&&gim_nonce_ok('gim_verify_email')){ $email=sanitize_email($_POST['verify_email']??''); $u=get_user_by('email',$email); $ok=$u?gim_verify_email_otp($u->ID,'verify',gim_post_text('verify_code')):false; echo $ok?'<div class="gim-alert">Email verified. You can log in now.</div>':'<div class="gim-alert gim-error">Invalid or expired verification code.</div>'; }
 echo '<main class="gim-shell"><div class="gim-grid"><div class="gim-card"><h2>Login</h2>'; wp_login_form(['redirect'=>gim_dashboard_url()]); echo '</div><div class="gim-card"><h2>Create customer account</h2><form method="post">'.wp_nonce_field('gim_register','_wpnonce',true,false).'<div class="gim-field"><label>Name</label><input name="name" required></div><div class="gim-field"><label>Email</label><input type="email" name="email" required></div><div class="gim-field"><label>Password</label><input type="password" name="password" minlength="10" required></div><button class="gim-btn green">Register</button></form><hr><h3>Verify email</h3><form method="post">'.wp_nonce_field('gim_verify_email','_wpnonce',true,false).'<div class="gim-field"><label>Email</label><input type="email" name="verify_email" required></div><div class="gim-field"><label>6-digit code</label><input name="verify_code" inputmode="numeric" required></div><button class="gim-btn">Verify Email</button></form></div></div></main>';
}
function gim_screen_customer_dashboard(){ gim_require_role('customer'); global $wpdb; $uid=get_current_user_id(); $jobs=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE customer_id=%d ORDER BY id DESC',$uid)); echo '<main class="gim-shell"><h1>Customer Dashboard</h1><p><a class="gim-btn green" href="'.esc_url(gim_page_url('gim-book-service')).'">Book a service</a> <a class="gim-btn" href="'.esc_url(gim_page_url('gim-provider-directory')).'">Find providers</a></p><div class="gim-card"><h2>Your jobs</h2><table class="gim-table"><tr><th>Job</th><th>Service</th><th>Status</th><th></th></tr>'; foreach($jobs as $j)echo '<tr><td>'.esc_html($j->reference).'</td><td>'.esc_html(ucwords(str_replace('-',' ',$j->service_slug))).'</td><td><span class="gim-badge">'.esc_html($j->status).'</span></td><td><a href="'.esc_url(gim_page_url('gim-job',['ref'=>$j->reference])).'">Open</a></td></tr>'; echo '</table></div></main>'; }
function gim_screen_provider_dashboard(){ gim_require_role('provider'); global $wpdb; $p=gim_provider_profile(get_current_user_id()); if(!$p){echo '<main class="gim-shell"><div class="gim-card">Provider profile not found.</div></main>';return;} if($_SERVER['REQUEST_METHOD']==='POST'&&gim_nonce_ok('gim_stripe_onboard')){ $r=gim_provider_stripe_onboarding(get_current_user_id()); if(is_wp_error($r))echo '<div class="gim-alert gim-error">'.esc_html($r->get_error_message()).'</div>'; else {wp_redirect(esc_url_raw($r));exit;} } $p=gim_provider_profile(get_current_user_id()); $jobs=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE provider_id=%d ORDER BY id DESC',$p->id)); echo '<main class="gim-shell"><h1>Provider Dashboard</h1><div class="gim-card"><strong>'.esc_html($p->business_name?:$p->public_id).'</strong> · '.esc_html($p->status).' · Stripe '.($p->stripe_ready?'ready':'not ready'); if(!$p->stripe_ready)echo '<form method="post" style="margin-top:12px">'.wp_nonce_field('gim_stripe_onboard','_wpnonce',true,false).'<button class="gim-btn green">Set up Stripe payouts</button></form>'; echo '</div><div class="gim-card"><h2>Jobs</h2><table class="gim-table">'; foreach($jobs as $j)echo '<tr><td>'.esc_html($j->reference).'</td><td>'.esc_html($j->status).'</td><td><a href="'.esc_url(gim_page_url('gim-job',['ref'=>$j->reference])).'">Open</a></td></tr>'; echo '</table></div></main>'; }
function gim_screen_book_service(){ gim_require_role('customer'); if($_SERVER['REQUEST_METHOD']==='POST'&&gim_nonce_ok('gim_book')){ $r=gim_create_job(get_current_user_id(),['service_slug'=>gim_post_text('service'),'description'=>gim_post_text('description'),'postcode'=>gim_post_text('postcode'),'urgency'=>gim_post_text('urgency')]); if(is_wp_error($r))echo '<div class="gim-alert gim-error">'.esc_html($r->get_error_message()).'</div>'; else {global $wpdb;$j=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$r));gim_redirect_notice(gim_page_url('gim-job',['ref'=>$j->reference]),'Job created. Enter the VJI code sent to your email.');} }
 echo '<main class="gim-shell"><div class="gim-card"><h1>Book a Service</h1><form method="post">'.wp_nonce_field('gim_book','_wpnonce',true,false).'<div class="gim-field"><label>Service</label><select name="service">'; foreach(gim_services() as $slug=>$s)echo '<option value="'.esc_attr($slug).'">'.esc_html($s['name']).'</option>'; echo '</select></div><div class="gim-field"><label>Describe the job</label><textarea name="description" required></textarea></div><div class="gim-field"><label>Postcode</label><input name="postcode" required></div><div class="gim-field"><label>Urgency</label><select name="urgency"><option>standard</option><option>urgent</option><option>emergency</option></select></div><button class="gim-btn green">Continue</button></form></div></main>'; }
function gim_screen_provider_directory(){ global $wpdb; $service=sanitize_key($_GET['service']??''); $rows=$wpdb->get_results("SELECT * FROM ".gim_table('providers')." WHERE status='approved' ORDER BY id DESC"); echo '<main class="gim-shell"><h1>Providers</h1><div class="gim-grid">'; foreach($rows as $p){ if($service&&!in_array($service,gim_decode($p->services_json),true))continue; echo '<div class="gim-card"><h3>'.esc_html($p->business_name?:$p->public_id).'</h3><p>'.esc_html(ucwords(str_replace('-',' ',$p->trade_family))).'</p>'; foreach(gim_decode($p->services_json) as $s){$oi=gim_latest_outcome($p->id,$s); if($oi)echo '<p class="gim-muted">'.esc_html($s).': verified outcome '.esc_html(round($oi->outcome_score)).'/100 · confidence '.esc_html(round($oi->confidence_score)).'%</p>'; } echo '</div>'; } echo '</div></main>'; }
function gim_screen_provider_apply(){ if(!is_user_logged_in())auth_redirect(); if($_SERVER['REQUEST_METHOD']==='POST'&&gim_nonce_ok('gim_provider_apply')){ $services=array_map('sanitize_key',(array)($_POST['services']??[])); $r=gim_create_provider_application(get_current_user_id(),['business_name'=>gim_post_text('business_name'),'trade_family'=>gim_post_text('trade_family'),'services'=>$services,'coverage'=>array_filter(array_map('trim',explode(',',gim_post_text('coverage'))))]); if(is_wp_error($r))echo '<div class="gim-alert gim-error">'.esc_html($r->get_error_message()).'</div>'; else echo '<div class="gim-alert">Application submitted for Admin review.</div>'; } echo '<main class="gim-shell"><div class="gim-card"><h1>Become a Provider</h1><form method="post">'.wp_nonce_field('gim_provider_apply','_wpnonce',true,false).'<div class="gim-field"><label>Business name</label><input name="business_name" required></div><div class="gim-field"><label>Trade family</label><input name="trade_family" required></div><div class="gim-field"><label>Services</label>'; foreach(gim_services() as $slug=>$s)echo '<label><input type="checkbox" name="services[]" value="'.esc_attr($slug).'"> '.esc_html($s['name']).'</label> '; echo '</div><div class="gim-field"><label>Coverage postcodes (comma separated)</label><input name="coverage"></div><button class="gim-btn green">Submit</button></form></div></main>'; }
function gim_screen_job(){ global $wpdb; $ref=sanitize_text_field($_GET['ref']??''); $job=gim_job_by_ref($ref); if(!$job){echo '<main class="gim-shell"><div class="gim-card">Job not found.</div></main>';return;} $role=gim_current_role(); $uid=get_current_user_id(); $owns=$role==='admin'||($role==='customer'&&gim_job_owned_by_customer($job,$uid))||($role==='provider'&&gim_job_owned_by_provider($job,$uid)); if(!$owns)wp_die('Not authorised.',403);
 if($_SERVER['REQUEST_METHOD']==='POST'&&gim_nonce_ok('gim_job_'.$job->id)){ $action=gim_post_text('gim_action'); $r=true;
  if($action==='vji_verify'&&$role==='customer')$r=gim_vji_verify($job->id,$uid,gim_post_text('code'));
  elseif($action==='request_provider'&&$role==='customer')$r=gim_send_job_request($job->id,gim_post_int('provider_id'),$uid);
  elseif($action==='provider_accept'&&$role==='provider')$r=gim_provider_respond_job($job->id,$uid,'accept');
  elseif($action==='provider_decline'&&$role==='provider')$r=gim_provider_respond_job($job->id,$uid,'decline');
  elseif($action==='send_estimate'&&$role==='provider'){ $items=[['type'=>'labour','label'=>'Labour','quantity'=>1,'unit_pence'=>(int)round(((float)($_POST['labour']??0))*100)],['type'=>'callout','label'=>'Call-out','quantity'=>1,'unit_pence'=>(int)round(((float)($_POST['callout']??0))*100)],['type'=>'emergency','label'=>'Emergency','quantity'=>1,'unit_pence'=>(int)round(((float)($_POST['emergency']??0))*100)],['type'=>'material','label'=>'Materials','quantity'=>1,'unit_pence'=>(int)round(((float)($_POST['materials']??0))*100)]]; $r=gim_create_estimate($job->id,$uid,$items); }
  elseif($action==='estimate_accept'&&$role==='customer')$r=gim_customer_decide_estimate(gim_post_int('estimate_id'),$uid,'accept');
  elseif($action==='estimate_reject'&&$role==='customer')$r=gim_customer_decide_estimate(gim_post_int('estimate_id'),$uid,'reject');
  elseif($action==='pay_initial'&&$role==='customer'){ $r=gim_create_checkout_for_job($job->id,$uid); if(!is_wp_error($r)&&!empty($r['url'])){wp_redirect(esc_url_raw($r['url']));exit;} }
  elseif($action==='start_job'&&$role==='provider')$r=gim_provider_start_job($job->id,$uid);
  elseif($action==='complete_job'&&$role==='provider')$r=gim_provider_complete_job($job->id,$uid);
  elseif($action==='confirm_completion'&&$role==='customer')$r=gim_customer_confirm_completion($job->id,$uid);
  elseif($action==='request_payout'&&$role==='provider')$r=gim_request_payout($job->id,$uid);
  elseif($action==='upload_material_invoice'&&$role==='provider'){ $lines=[]; if(gim_post_text('material_name'))$lines[]=['name'=>gim_post_text('material_name'),'quantity'=>(float)($_POST['material_qty']??1),'unit_pence'=>(int)round(((float)($_POST['material_unit']??0))*100)]; $r=gim_upload_material_invoice($job->id,$uid,(int)round(((float)($_POST['material_actual']??0))*100),$lines); }
  elseif($action==='propose_additional_work'&&$role==='provider'){ $items=[['type'=>'labour','label'=>'Additional labour/service','quantity'=>1,'unit_pence'=>(int)round(((float)($_POST['extra_service']??0))*100)],['type'=>'material','label'=>'Additional materials','quantity'=>1,'unit_pence'=>(int)round(((float)($_POST['extra_materials']??0))*100)]]; $r=gim_propose_additional_work($job->id,$uid,gim_post_text('extra_reason'),$items); }
  elseif($action==='additional_approve'&&$role==='customer')$r=gim_customer_decide_additional_work(gim_post_int('additional_id'),$uid,'approve');
  elseif($action==='additional_reject'&&$role==='customer')$r=gim_customer_decide_additional_work(gim_post_int('additional_id'),$uid,'reject');
  elseif($action==='pay_topup'&&$role==='customer'){ $r=gim_create_checkout_for_job($job->id,$uid,'top_up_service',gim_post_int('additional_id')); if(!is_wp_error($r)&&!empty($r['url'])){wp_redirect(esc_url_raw($r['url']));exit;} }
  elseif($action==='open_dispute'&&$role==='customer')$r=gim_open_dispute($job->id,$uid,gim_post_text('reason'));
  if(is_wp_error($r))echo '<div class="gim-alert gim-error">'.esc_html($r->get_error_message()).'</div>'; else gim_redirect_notice(gim_page_url('gim-job',['ref'=>$job->reference]),'Action completed.');
 }
 $job=gim_job_by_ref($ref); echo '<main class="gim-shell"><h1>'.esc_html($job->reference).'</h1><div class="gim-grid"><div class="gim-card"><h3>Job</h3><p><strong>Service:</strong> '.esc_html(ucwords(str_replace('-',' ',$job->service_slug))).'</p><p><strong>Status:</strong> <span class="gim-badge">'.esc_html($job->status).'</span></p><p>'.esc_html($job->description).'</p><p><strong>VJI:</strong> '.esc_html($job->vji_status).'</p></div><div class="gim-card"><h3>Actions</h3>';
 $nonce=wp_nonce_field('gim_job_'.$job->id,'_wpnonce',true,false);
 if($role==='customer'&&$job->vji_status!=='verified')echo '<form method="post">'.$nonce.'<input type="hidden" name="gim_action" value="vji_verify"><div class="gim-field"><label>VJI code</label><input name="code" required></div><button class="gim-btn green">Verify Job Intent</button></form>';
 if($role==='customer'&&$job->status==='verified_intent'){ $matches=gim_match_providers($job); echo '<form method="post">'.$nonce.'<input type="hidden" name="gim_action" value="request_provider"><div class="gim-field"><label>Choose Provider</label><select name="provider_id">'; foreach($matches as $m)echo '<option value="'.(int)$m['provider']->id.'">'.esc_html($m['provider']->business_name?:$m['provider']->public_id).'</option>'; echo '</select></div><button class="gim-btn green">Send Job Request</button></form>'; }
 if($role==='provider'&&$job->status==='provider_requested')echo '<form method="post">'.$nonce.'<button class="gim-btn green" name="gim_action" value="provider_accept">Accept</button> <button class="gim-btn danger" name="gim_action" value="provider_decline">Decline</button></form>';
 if($role==='provider'&&in_array($job->status,['provider_accepted','estimate_sent'],true))echo '<form method="post">'.$nonce.'<input type="hidden" name="gim_action" value="send_estimate"><div class="gim-field"><label>Labour £</label><input type="number" step="0.01" name="labour" required></div><div class="gim-field"><label>Call-out £</label><input type="number" step="0.01" name="callout"></div><div class="gim-field"><label>Emergency £</label><input type="number" step="0.01" name="emergency"></div><div class="gim-field"><label>Materials £</label><input type="number" step="0.01" name="materials"></div><button class="gim-btn">Send Estimate</button></form>';
 $est=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('estimates').' WHERE job_id=%d ORDER BY id DESC LIMIT 1',$job->id)); if($est)echo '<p>Latest estimate: '.esc_html(gim_money($est->total_pence)).' (service '.esc_html(gim_money($est->service_subtotal_pence)).', materials '.esc_html(gim_money($est->materials_subtotal_pence)).') · '.esc_html($est->status).'</p>';
 if($role==='customer'&&$est&&$est->status==='sent')echo '<form method="post">'.$nonce.'<input type="hidden" name="estimate_id" value="'.(int)$est->id.'"><button class="gim-btn green" name="gim_action" value="estimate_accept">Accept Estimate</button> <button class="gim-btn danger" name="gim_action" value="estimate_reject">Reject</button></form>';
 if($role==='customer'&&$job->status==='payment_required')echo '<form method="post">'.$nonce.'<button class="gim-btn green" name="gim_action" value="pay_initial">Pay Securely</button></form>';
 if($role==='provider'&&in_array($job->status,['payment_secured','scheduled'],true))echo '<form method="post">'.$nonce.'<button class="gim-btn green" name="gim_action" value="start_job">Start Job</button></form>';
 if($role==='provider'&&$job->status==='in_progress')echo '<form method="post">'.$nonce.'<button class="gim-btn green" name="gim_action" value="complete_job">Mark Work Complete</button></form>';
 if($role==='customer'&&$job->status==='provider_completed')echo '<form method="post">'.$nonce.'<button class="gim-btn green" name="gim_action" value="confirm_completion">Confirm Completion</button></form>';
 if($role==='provider'&&$job->status==='completed')echo '<form method="post">'.$nonce.'<button class="gim-btn" name="gim_action" value="request_payout">Request Payout</button></form>';
 $mat=gim_material_plan($job->id); if($role==='provider'&&in_array($job->status,['payment_secured','scheduled','in_progress'],true)&&$est&&$est->materials_subtotal_pence>0){ if(!$mat)gim_set_material_plan($job->id,$est->materials_subtotal_pence,true); echo '<hr><h4>Materials transparency</h4><form method="post" enctype="multipart/form-data">'.$nonce.'<input type="hidden" name="gim_action" value="upload_material_invoice"><div class="gim-field"><label>Receipt / invoice</label><input type="file" name="invoice" required></div><div class="gim-field"><label>Actual materials total £</label><input type="number" step="0.01" name="material_actual" required></div><div class="gim-field"><label>Material item (optional)</label><input name="material_name"></div><div class="gim-field"><label>Quantity</label><input type="number" step="0.01" name="material_qty" value="1"></div><div class="gim-field"><label>Unit price £</label><input type="number" step="0.01" name="material_unit"></div><button class="gim-btn">Upload & AI Check</button></form>'; }
 $aw=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".gim_table('additional_work')." WHERE job_id=%d ORDER BY id DESC LIMIT 1",$job->id)); if($role==='provider'&&$job->status==='in_progress'&&(!$aw||in_array($aw->status,['customer_rejected','payment_secured','cancelled'],true)))echo '<hr><h4>Additional work</h4><form method="post">'.$nonce.'<input type="hidden" name="gim_action" value="propose_additional_work"><div class="gim-field"><label>Reason / extra scope</label><textarea name="extra_reason" required></textarea></div><div class="gim-field"><label>Extra service £</label><input type="number" step="0.01" name="extra_service" required></div><div class="gim-field"><label>Extra materials £</label><input type="number" step="0.01" name="extra_materials"></div><button class="gim-btn">Send additional-work request</button></form>'; if($aw){ echo '<p><strong>Additional work:</strong> '.esc_html($aw->status).' · service '.esc_html(gim_money($aw->service_pence)).' · materials '.esc_html(gim_money($aw->materials_pence)).'</p>'; if($role==='customer'&&$aw->status==='proposed')echo '<form method="post">'.$nonce.'<input type="hidden" name="additional_id" value="'.(int)$aw->id.'"><button class="gim-btn green" name="gim_action" value="additional_approve">Approve</button> <button class="gim-btn danger" name="gim_action" value="additional_reject">Reject</button></form>'; if($role==='customer'&&$aw->status==='customer_approved')echo '<form method="post">'.$nonce.'<input type="hidden" name="additional_id" value="'.(int)$aw->id.'"><button class="gim-btn green" name="gim_action" value="pay_topup">Pay Top-Up</button></form>'; }
 if($role==='customer'&&in_array($job->status,['in_progress','provider_completed','completed'],true))echo '<hr><form method="post">'.$nonce.'<input type="hidden" name="gim_action" value="open_dispute"><div class="gim-field"><label>Problem / dispute reason</label><textarea name="reason" required></textarea></div><button class="gim-btn danger">Open Dispute</button></form>';
 echo '</div></div></main>'; }
function gim_screen_payment_return(){ echo '<main class="gim-shell"><div class="gim-card"><h1>Payment received</h1><p>Your payment is only treated as secured after GOTITMATE receives the verified Stripe webhook. You can return to your dashboard.</p><a class="gim-btn" href="'.esc_url(gim_dashboard_url()).'">Dashboard</a></div></main>'; }
function gim_screen_disputes(){ if(!is_user_logged_in())auth_redirect(); global $wpdb; $role=gim_current_role(); if($role==='customer')$rows=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.gim_table('disputes').' WHERE customer_id=%d ORDER BY id DESC',get_current_user_id())); elseif($role==='provider'){ $p=gim_provider_profile(get_current_user_id()); $rows=$p?$wpdb->get_results($wpdb->prepare('SELECT * FROM '.gim_table('disputes').' WHERE provider_id=%d ORDER BY id DESC',$p->id)):[]; } else $rows=$wpdb->get_results('SELECT * FROM '.gim_table('disputes').' ORDER BY id DESC'); echo '<main class="gim-shell"><div class="gim-card"><h1>Disputes</h1><table class="gim-table">'; foreach($rows as $d)echo '<tr><td>'.esc_html($d->reference).'</td><td>'.esc_html($d->status).'</td><td>'.esc_html($d->reason).'</td><td>'.esc_html($d->resolution?:'—').'</td></tr>'; echo '</table></div></main>'; }
function gim_screen_admin_dashboard(){ gim_require_role('admin'); global $wpdb;
 if($_SERVER['REQUEST_METHOD']==='POST'&&gim_nonce_ok('gim_admin')){ $a=gim_post_text('gim_action'); $r=true; if($a==='approve_provider')$r=gim_admin_set_provider_status(gim_post_int('provider_id'),'approved',['identity'=>true,'insurance'=>true,'qualifications'=>[]]); elseif($a==='release_payout')$r=gim_admin_release_payout(gim_post_int('payout_id')); elseif($a==='resolve_dispute')$r=gim_admin_resolve_dispute(gim_post_int('dispute_id'),gim_post_text('resolution'),(int)round(((float)($_POST['refund']??0))*100),gim_post_text('notes')); if(is_wp_error($r))echo '<div class="gim-alert gim-error">'.esc_html($r->get_error_message()).'</div>'; else gim_redirect_notice(gim_page_url('gim-admin-dashboard'),'Admin action completed.'); }
 $n=wp_nonce_field('gim_admin','_wpnonce',true,false); $providers=$wpdb->get_results("SELECT * FROM ".gim_table('providers')." WHERE status='pending'"); $payouts=$wpdb->get_results("SELECT * FROM ".gim_table('payouts')." WHERE status='requested'"); $disputes=$wpdb->get_results("SELECT * FROM ".gim_table('disputes')." WHERE status NOT IN ('resolved','closed')"); echo '<main class="gim-shell"><h1>GOTITMATE Admin</h1><div class="gim-grid"><div class="gim-card"><h2>Provider approvals</h2>'; foreach($providers as $p)echo '<form method="post">'.$n.'<input type="hidden" name="provider_id" value="'.(int)$p->id.'"><p>'.esc_html($p->business_name).' · '.esc_html($p->public_id).' <button class="gim-btn green" name="gim_action" value="approve_provider">Approve verified</button></p></form>'; echo '</div><div class="gim-card"><h2>Payout requests</h2>'; foreach($payouts as $p)echo '<form method="post">'.$n.'<input type="hidden" name="payout_id" value="'.(int)$p->id.'"><p>'.esc_html($p->reference).' · '.esc_html(gim_money($p->provider_pence)).' <button class="gim-btn" name="gim_action" value="release_payout">Release via Stripe</button></p></form>'; echo '</div><div class="gim-card"><h2>Open disputes</h2>'; foreach($disputes as $d)echo '<form method="post">'.$n.'<input type="hidden" name="dispute_id" value="'.(int)$d->id.'"><p><strong>'.esc_html($d->reference).'</strong> '.esc_html($d->reason).'</p><select name="resolution"><option>NO_FINANCIAL_ADJUSTMENT</option><option>FULL_REFUND</option><option>PARTIAL_REFUND</option><option>RELEASE_PAYMENT</option><option>PARTIAL_RELEASE</option><option>OTHER</option></select><input name="refund" type="number" step="0.01" placeholder="Refund £"><textarea name="notes" placeholder="Admin notes"></textarea><button class="gim-btn" name="gim_action" value="resolve_dispute">Resolve</button></form>'; echo '</div></div></main>'; }
